package org.vechain.indexer

import io.mockk.*
import io.mockk.impl.annotations.MockK
import io.mockk.junit5.MockKExtension
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.extension.ExtendWith
import org.springframework.data.mongodb.core.MongoTemplate
import org.vechain.indexer.fixtures.BlockFixtures.BLOCK_3_NO_CLAUSES
import org.vechain.indexer.fixtures.BlockFixtures.BLOCK_4_SINGLE_CLAUSE
import org.vechain.indexer.model.IndexedTransaction
import org.vechain.indexer.repository.TransactionRepository
import strikt.api.expect
import strikt.assertions.hasSize
import strikt.assertions.isEqualTo
import strikt.assertions.isNull

@ExtendWith(MockKExtension::class)
internal class TransactionIndexerTest {

    @MockK
    lateinit var transactionRepository: TransactionRepository

    @MockK
    lateinit var mongoTemplate: MongoTemplate

    lateinit var transactionIndexer: TransactionIndexer

    @BeforeEach
    fun setUp() {
        MockKAnnotations.init(this)
        transactionIndexer = TransactionIndexer(transactionRepository, mongoTemplate, "http://localhost:8669", 0L)
    }

    @Test
    fun `Process block - With no transactions`() {

        transactionIndexer.processBlock(BLOCK_3_NO_CLAUSES)

        verify { mongoTemplate wasNot Called }
    }

    @Test
    fun `Process block - With transactions`() {

        val transactionsSlot = slot<List<IndexedTransaction>>()
        every {
            mongoTemplate.insert(
                capture(transactionsSlot),
                IndexedTransaction::class.java
            )
        } returns mutableListOf()

        transactionIndexer.processBlock(BLOCK_4_SINGLE_CLAUSE)

        val txs = transactionsSlot.captured
        expect {
            that(txs).hasSize(1)
        }
        val transaction = txs.first()
        expect {
            that(transaction).get(IndexedTransaction::id)
                .isEqualTo("0x9e8d79999a360990bc849a49bced505a66958f5707d6e7640398b596136c942d")
            that(transaction).get(IndexedTransaction::size).isEqualTo(8551)
            that(transaction).get(IndexedTransaction::chainTag).isEqualTo(246)
            that(transaction).get(IndexedTransaction::blockRef).isEqualTo("0x00000003dc993afc")
            that(transaction).get(IndexedTransaction::expiration).isEqualTo(18)
            that(transaction).get(IndexedTransaction::clauses).hasSize(1)
                .and {
                    that(transaction.clauses.first().to).isNull()
                    that(transaction.clauses.first().value).isEqualTo("0x0")
                    that(transaction.clauses.first().data).isEqualTo(
                        ""
                    )
                }
            that(transaction).get(IndexedTransaction::gasPayer).isEqualTo("0xf077b491b355e64048ce21e3a6fc4751eeea77fa")
            that(transaction).get(IndexedTransaction::origin).isEqualTo("0xf077b491b355e64048ce21e3a6fc4751eeea77fa")
        }
    }
}